/* ============================================
   THEME TOGGLE
   The colour-mode control. It is a
   SegmentedControl, which draws every pixel;
   this root keeps the strip at its own width
   in a squeezed row, and dresses the icon-only
   form.
   ============================================ */

.ds-theme-toggle {
  flex-shrink: 0;
}

/* ============================================
   ICON STRIP (showLabels={false})
   The glyphs alone, with each label turned
   into the segment's tooltip: it appears below
   the segment on hover and keyboard focus, on
   Tooltip's surface, so "routine" is never
   left to be guessed as System. The component
   places the label with the shared
   anchored-position behaviour, so a seat that
   clips cannot cut it off, and it flips above
   the strip when there is no room below. The label
   stays in the accessibility tree as the
   segment's name. This is the documentation
   site's header toggle, moved into the
   package so a consumer's strip behaves the
   same.
   ============================================ */

.ds-theme-toggle--icons .ds-segmented-control__label {
  /* Out of flow at rest; the behaviour makes it fixed once it shows. */
  position: absolute;
  z-index: var(--layer-floating);
  padding: var(--padding-150) var(--padding-200);
  border-radius: var(--radius-100);
  border: var(--border-025) solid var(--color-bg-container-border);
  background-color: var(--color-bg-page-primary);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-floating);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translateY(calc(-1 * var(--gap-100)));
  transition:
    opacity var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard);
}

/* --motion-duration-slow matches MOTION_HOVER_SHOW_DELAY_MS, the hover-intent
   delay Tooltip uses in JS, so the label does not flash while the pointer
   passes through. Hiding takes no delay, like a tooltip leaving. */
.ds-theme-toggle--icons .ds-segmented-control__segment:hover .ds-segmented-control__label,
.ds-theme-toggle--icons .ds-segmented-control__segment:focus-visible .ds-segmented-control__label {
  opacity: 1;
  transform: none;
  transition-delay: var(--motion-duration-slow);
}

/* Flipped above the strip, it slides down into place instead. */
.ds-theme-toggle--icons .ds-segmented-control__label[data-side='top'] {
  transform: translateY(var(--gap-100));
}

/* Without an inline label a segment's asymmetric padding reads lopsided:
   square each one into an even pill around its glyph. */
.ds-theme-toggle--icons .ds-segmented-control__segment {
  padding-inline: var(--padding-200);
}

/* ds-allow(motion): drops the label tooltip's slide outright rather than playing it at 0.01ms. */
@media (prefers-reduced-motion: reduce) {
  .ds-theme-toggle--icons .ds-segmented-control__label {
    transition: none;
  }
}

'use client';

import React, { useRef, useState } from 'react';
import { SegmentedControl } from '../SegmentedControl/SegmentedControl';
import { useAnchoredPosition } from '../../behaviors/useAnchoredPosition';
import type { ColorModeSetting } from './colorMode';
import { useColorMode } from './useColorMode';
import './ThemeToggle.css';

/** Props owned by ThemeToggle itself — everything else falls through to the strip. */
type ThemeToggleOwnProps = {
  /** Control size, on SegmentedControl's scale. */
  size?: 'default' | 'compact';
  /** Show each segment's label beside its icon. Set `false` for an icon-only strip: each label becomes the segment's tooltip on hover and keyboard focus, and stays its accessible name. */
  showLabels?: boolean;
  /** The localStorage key the choice is kept under. Match the key given to `colorModeScript`. Default `theme`. */
  storageKey?: string;
  /** Label of the setting that follows the operating system. */
  systemLabel?: string;
  /** Label of the light setting. */
  lightLabel?: string;
  /** Label of the dark setting. */
  darkLabel?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface ThemeToggleProps
  extends ThemeToggleOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof ThemeToggleOwnProps | 'children' | 'onChange' | 'defaultValue'> {}

/**
 * The colour-mode control: System, Light and Dark on a SegmentedControl,
 * over `useColorMode`, so every instance on a page stays in step and the
 * choice survives a reload. Pair it with `colorModeScript` in the document
 * head, which applies the stored choice before first paint.
 *
 * Forwards a ref to the strip and spreads unrecognised props onto it.
 */
export const ThemeToggle = React.forwardRef<HTMLDivElement, ThemeToggleProps>(
  (
    {
      size = 'compact',
      showLabels = true,
      storageKey,
      systemLabel = 'System',
      lightLabel = 'Light',
      darkLabel = 'Dark',
      className = '',
      'aria-label': ariaLabel = 'Colour mode',
      ...rest
    },
    ref,
  ) => {
    const [setting, setSetting] = useColorMode({ storageKey });

    // The icon strip's tooltips: the label of the segment under the pointer
    // or keyboard focus is placed against its segment by the shared
    // anchored-position behaviour, so a seat that clips (a sidebar's floor)
    // cannot cut it off, and it flips above when there is no room below.
    const stripRef = useRef<HTMLDivElement | null>(null);
    const segmentRef = useRef<HTMLElement | null>(null);
    const labelRef = useRef<HTMLElement | null>(null);
    const [tip, setTip] = useState<number | null>(null);
    const setStripRef = (node: HTMLDivElement | null) => {
      stripRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };
    const showTip = (target: EventTarget | null) => {
      if (showLabels) return;
      const segment = (target as HTMLElement | null)?.closest<HTMLElement>('.ds-segmented-control__segment');
      const strip = stripRef.current;
      if (!segment || !strip) return;
      segmentRef.current = segment;
      labelRef.current = segment.querySelector<HTMLElement>('.ds-segmented-control__label');
      setTip([...strip.querySelectorAll('.ds-segmented-control__segment')].indexOf(segment));
    };
    useAnchoredPosition({
      open: tip !== null,
      target: tip,
      anchorRef: segmentRef,
      panelRef: labelRef,
      side: 'bottom',
      align: 'center',
      gapProperty: '--gap-100',
    });
    const segments = [
      { value: 'system', label: systemLabel, icon: 'routine' },
      { value: 'light', label: lightLabel, icon: 'light_mode' },
      { value: 'dark', label: darkLabel, icon: 'dark_mode' },
    ];
    return (
      <SegmentedControl
        aria-label={ariaLabel}
        {...rest}
        ref={setStripRef}
        onPointerOver={(event) => {
          rest.onPointerOver?.(event);
          showTip(event.target);
        }}
        onFocus={(event) => {
          rest.onFocus?.(event);
          showTip(event.target);
        }}
        className={['ds-theme-toggle', !showLabels && 'ds-theme-toggle--icons', className]
          .filter(Boolean)
          .join(' ')}
        segments={segments}
        value={setting}
        onValueChange={(value) => setSetting(value as ColorModeSetting)}
        size={size}
        // The icon strip keeps its labels rendered: the stylesheet turns each
        // into the segment's tooltip, so the glyphs are never left unnamed.
        showLabels
      />
    );
  },
);

ThemeToggle.displayName = 'ThemeToggle';

/**
 * Colour mode: the visitor's choice of system, light or dark, applied to the
 * page as the `data-theme` the tokens read.
 *
 * Two attributes on `<html>` carry it. `data-theme-setting` is the choice
 * (`system`, `light` or `dark`); `data-theme` is what it resolves to
 * (`light` or `dark`), which every stylesheet and component reads. While the
 * setting is `system`, the page follows the operating system.
 *
 * `colorModeScript()` applies the stored choice before first paint, so a
 * returning visitor never sees the wrong mode flash; render it in the
 * document head. `useColorMode()` reads and changes the choice from any
 * component, and every instance stays in step, across tabs too. ThemeToggle
 * is the control built on it, and useColorMode.tsx holds the hook.
 *
 * This module holds the script and the vocabulary, and is safe to import
 * from a Server Component (a root layout renders the script); the hook
 * lives in `useColorMode.tsx`, a client module. Both are kept out of
 * ThemeToggle.tsx so that module exports only a component (react-refresh).
 * `.tsx` despite holding no JSX: the barrel generator and the
 * `./components/*` export subpath both address `.tsx`, so that extension is
 * what makes this reachable as `rift-ds/components/ThemeToggle/colorMode`.
 */

/** The three settings, in the order every colour-mode control shows them. */
export const colorModeSettings = ['system', 'light', 'dark'] as const;

export type ColorModeSetting = (typeof colorModeSettings)[number];

/** Where the choice is stored unless a caller names its own key. */
export const DEFAULT_COLOR_MODE_STORAGE_KEY = 'theme';

export const isColorModeSetting = (value: unknown): value is ColorModeSetting =>
  colorModeSettings.includes(value as ColorModeSetting);

/** The options both halves share, so the script and the hook agree on a key. */
export type ColorModeOptions = {
  /** The localStorage key the choice is kept under. Default `theme`. */
  storageKey?: string;
};

/**
 * The script that applies the stored choice before first paint: it sets
 * `data-theme-setting` and `data-theme` on `<html>` and, while the setting
 * is `system`, keeps `data-theme` following the operating system. Render it
 * inline in the document head, before anything paints. Storage being
 * unavailable (a private window) leaves the page on `system`.
 */
export function colorModeScript({ storageKey = DEFAULT_COLOR_MODE_STORAGE_KEY }: ColorModeOptions = {}): string {
  const key = JSON.stringify(storageKey);
  return `(function () {
  var root = document.documentElement;
  var saved = null;
  try { saved = localStorage.getItem(${key}); } catch (e) {}
  var setting = saved === 'light' || saved === 'dark' ? saved : 'system';
  var media = window.matchMedia('(prefers-color-scheme: dark)');
  root.setAttribute('data-theme-setting', setting);
  root.setAttribute('data-theme', setting === 'system' ? (media.matches ? 'dark' : 'light') : setting);
  media.addEventListener('change', function (event) {
    if (root.getAttribute('data-theme-setting') === 'system') {
      root.setAttribute('data-theme', event.matches ? 'dark' : 'light');
    }
  });
})();`;
}

'use client';

/**
 * `useColorMode`, the client half of colour mode (see `colorMode.tsx`): the
 * visitor's setting and the one way to change it.
 */
import { useCallback, useSyncExternalStore } from 'react';
import {
  DEFAULT_COLOR_MODE_STORAGE_KEY,
  isColorModeSetting,
  type ColorModeOptions,
  type ColorModeSetting,
} from './colorMode';

function subscribe(callback: () => void) {
  const observer = new MutationObserver(callback);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['data-theme-setting'],
  });
  window.addEventListener('storage', callback);
  return () => {
    observer.disconnect();
    window.removeEventListener('storage', callback);
  };
}

function getSnapshot(): ColorModeSetting {
  const value = document.documentElement.getAttribute('data-theme-setting');
  return isColorModeSetting(value) ? value : 'system';
}

/** The server renders `system`: the pre-paint script sets the real value before hydration reads it. */
function getServerSnapshot(): ColorModeSetting {
  return 'system';
}

/**
 * The visitor's colour-mode setting and the one way to change it. Setting it
 * resolves `system` against the operating system, writes both attributes on
 * `<html>` and stores the choice; every instance updates through the
 * attribute, so no two controls can disagree.
 */
export function useColorMode({
  storageKey = DEFAULT_COLOR_MODE_STORAGE_KEY,
}: ColorModeOptions = {}): [setting: ColorModeSetting, setSetting: (setting: ColorModeSetting) => void] {
  const setting = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

  const setSetting = useCallback(
    (next: ColorModeSetting) => {
      const root = document.documentElement;
      root.setAttribute('data-theme-setting', next);
      const resolved =
        next === 'system'
          ? window.matchMedia('(prefers-color-scheme: dark)').matches
            ? 'dark'
            : 'light'
          : next;
      root.setAttribute('data-theme', resolved);
      try {
        localStorage.setItem(storageKey, next);
      } catch {
        // Storage unavailable: the choice lasts the page, which is all a private window allows.
      }
    },
    [storageKey],
  );

  return [setting, setSetting];
}
